import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.DDY-poMm.js";const g=JSON.parse('{"title":"后台登录与权限","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/admin-login.md","filePath":"zh/guide/admin-login.md","lastUpdated":1790683574000}'),o={name:"zh/guide/admin-login.md"};function i(s,t,n,l,h,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="后台登录与权限" tabindex="-1">后台登录与权限 <a class="header-anchor" href="#后台登录与权限" aria-label="Permalink to &quot;后台登录与权限&quot;">​</a></h1><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>运营后台需要管理员账号登录，登录时需填写图形验证码。</p><p>平台支持<strong>谷歌二次验证（2FA）</strong>：开启后，管理员在输入账号密码之后还需输入谷歌验证器上的动态验证码才能进入后台。该开关在后台配置中控制。</p><div class="warning custom-block"><p class="custom-block-title">建议</p><p>后台账号是平台的最高权限入口，<strong>强烈建议开启谷歌二次验证</strong>，并为每位运营人员分配独立账号，不要多人共用。</p></div><p>失败次数过多的账号会被临时锁定，找回密码同样有失败次数限制。</p><h2 id="权限模型" tabindex="-1">权限模型 <a class="header-anchor" href="#权限模型" aria-label="Permalink to &quot;权限模型&quot;">​</a></h2><p>后台采用<strong>角色 + 菜单权限</strong>模型：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>管理员账号  →  分配角色  →  角色决定能看到哪些菜单、能做哪些操作</span></span></code></pre></div><ul><li>在「系统管理 → 角色管理」中创建角色并勾选权限</li><li>在「系统管理 → 用户管理」中为管理员分配角色</li><li>未被授权的菜单不会出现在该账号的后台界面中</li></ul><h2 id="超级管理员专属配置" tabindex="-1">超级管理员专属配置 <a class="header-anchor" href="#超级管理员专属配置" aria-label="Permalink to &quot;超级管理员专属配置&quot;">​</a></h2><p>有一类配置项<strong>只有超级管理员能修改</strong>，普通运营角色即使有配置菜单的权限也无法保存。这是有意为之——这些配置一旦被误改或恶意修改，后果是<strong>安全级或全平台级</strong>的：</p><table tabindex="0"><thead><tr><th>配置项</th><th>改错的后果</th></tr></thead><tbody><tr><td>充值通道</td><td>入金可能被改道</td></tr><tr><td>提现通道</td><td>出金链路异常</td></tr><tr><td>第三方充提通道</td><td>同上</td></tr><tr><td>支付网关选择</td><td>入金通道切换错误</td></tr><tr><td>支付通道密钥</td><td>资金安全</td></tr><tr><td>后台登录二次验证开关</td><td>关闭后台的 2FA 保护</td></tr><tr><td>后台 IP 白名单</td><td>放开后台访问来源限制</td></tr><tr><td>行情源配置</td><td>行情价格来源被指向错误的服务，可能影响成交价</td></tr><tr><td>汇率配置</td><td>以外币计价的标的（如港股、A 股）成交价按错误比例偏移</td></tr><tr><td>App 版本更新</td><td>强制更新开关能让全体旧版本用户无法使用 App，详见 <a href="/CoinExchange/zh/guide/app-release">App 版本发布</a></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">请注意</p><p>上表中的配置项<strong>不建议在业务高峰期修改</strong>。修改前请确认自己清楚每一项的含义，必要时先与技术方确认。</p></div><h2 id="建议的账号分工" tabindex="-1">建议的账号分工 <a class="header-anchor" href="#建议的账号分工" aria-label="Permalink to &quot;建议的账号分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>建议权限</th></tr></thead><tbody><tr><td>超级管理员</td><td>全部。仅限 1～2 人持有，用于配置类操作</td></tr><tr><td>财务</td><td>充值记录、提现审核、资金流水、归集</td></tr><tr><td>客服</td><td>用户查询、实名审核、帮助中心与公告、客服会话记录</td></tr><tr><td>运营</td><td>站点配置（不含上表超管专属项）、币种管理、玩法配置、数据看板</td></tr></tbody></table>',16)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
